    public static void main(String[] args) {
        call();
    }
}

class FastException extends RuntimeException {
    FastException(String m) {
        super(m);
    }
}
public class Main {
    static void execute() {
        throw new FastException("FAST");
    }
    public static void main(String[] args) {
        try {
            execute();
        } catch (RuntimeException e) {
            System.out.println(e.getMessage());
        }
    }
}

